// === NAME - DESCRIPTION: Classify a study as observational or experimental, identify bias/confounding, and determine justified conclusions. ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
$scenarios = [
  [
    "context" => "A researcher wants to know if a new herbal tea improves memory. They recruit 100 volunteers and ask them to record their current tea-drinking habits. For six months, those who already drink herbal tea are compared to those who drink black tea or no tea in terms of their scores on a memory test.",
    "type" => "observational",
    "bias" => "self-selection",
    "confounding" => "lifestyle",
    "justified" => "there is an association between herbal tea consumption and memory scores",
    "not_justified" => "drinking herbal tea causes an improvement in memory",
    "explanation" => "The researcher did not assign the tea; they observed existing habits. Because volunteers chose their tea, other factors (like overall health or diet) might be the real cause of the memory difference."
  ],
  [
    "context" => "A school district wants to test a new math software. They randomly assign half of the 4th grade classrooms to use the software for one hour a day, while the other half continues with the standard curriculum. At the end of the year, they compare the average test scores of the two groups.",
    "type" => "experimental",
    "bias" => "none",
    "confounding" => "none",
    "justified" => "the new math software caused the difference in test scores",
    "not_justified" => "the software will work exactly the same way for students in other districts",
    "explanation" => "The district actively manipulated the independent variable by randomly assigning the software. Random assignment helps control for confounding variables, allowing for a causal conclusion."
  ],
  [
    "context" => "A nutritionist wants to see if eating blueberries improves focus. She recruits 50 students and asks them to keep a food diary for a month. She then analyzes the diaries and finds that students who naturally eat more blueberries have higher average GPAs.",
    "type" => "observational",
    "bias" => "recall",
    "confounding" => "socioeconomic status",
    "justified" => "students who eat more blueberries tend to have higher GPAs",
    "not_justified" => "eating blueberries increases a student's GPA",
    "explanation" => "This is observational because the nutritionist did not assign the blueberry intake. A confounding variable, such as family income, might influence both the ability to buy fresh blueberries and access to tutoring."
  ]
];

$pick = randfrom($scenarios);
$s = $pick;

$anstypes = "choices,string,string";

// Part 0: Classification
$questions[0] = ["Observational Study", "Experimental Study"];
$answer[0] = ($s['type'] == "observational") ? 0 : 1;

// Part 1: Bias/Confounding
$answer[1] = $s['bias'] . " or " . $s['confounding'] . " or confounding variable or selection bias or recall bias";
$strflags[1] = "ignore_case,trim_whitespace";

// Part 2: Conclusion
$answer[2] = $s['not_justified'] . " or causes or cause";
$strflags[2] = "ignore_case,trim_whitespace";

$solutionguide = "This study is " . $s['type'] . " because " . $s['explanation'] . " Therefore, we can state that " . $s['justified'] . ", but we cannot conclude that " . $s['not_justified'] . ".";

// === QUESTION TEXT ===
<p>Read the following study description:</p>
<blockquote style='font-style: italic;'>
  $s[context]
</blockquote>

<p><b>(a)</b> Which of the following best describes this study?</p>
$answerbox[0]

<p><b>(b)</b> Identify one plausible source of bias or a confounding variable that could affect the results of this study.</p>
$answerbox[1]

<p><b>(c)</b> Based on the design of this study, what is one conclusion that is <b>NOT</b> justified? (Specifically, address whether a causal relationship can be claimed.)</p>
$answerbox[2]

// === NAME - DESCRIPTION: Independence Expected Counts (2x2) - Compute three expected cells from row and column totals ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
# Randomize the observed counts for a 2x2 table
# We use separate variables instead of a nested array to avoid IMathAS array-to-string conversion warnings
$obs00 = rand(20, 50);
$obs01 = rand(20, 50);
$obs10 = rand(20, 50);
$obs11 = rand(20, 50);

# Calculate row and column totals
$row0 = $obs00 + $obs01;
$row1 = $obs10 + $obs11;
$col0 = $obs00 + $obs10;
$col1 = $obs01 + $obs11;
$grandTotal = $row0 + $row1;

# Calculate expected counts: (Row Total * Col Total) / Grand Total
$exp00 = ($row0 * $col0) / $grandTotal;
$exp01 = ($row0 * $col1) / $grandTotal;
$exp10 = ($row1 * $col0) / $grandTotal;
$exp11 = ($row1 * $col1) / $grandTotal;

# We ask for 3 of the 4 cells to avoid redundancy
$omit = rand(0, 3);

# Map the expected values to an array for indexing
$expectedValues = array($exp00, $exp01, $exp10, $exp11);

# Set the answer types for the 3 parts
$anstypes = "number,number,number";

# Determine which 3 cells the student will calculate
$cellsToCompute = array();
for ($i = 0; $i < 4; $i++) {
  if ($i != $omit) {
    $cellsToCompute[] = $i;
  }
}

# Assign answers based on the selected cells
$answer[0] = $expectedValues[$cellsToCompute[0]];
$answer[1] = $expectedValues[$cellsToCompute[1]];
$answer[2] = $expectedValues[$cellsToCompute[2]];

# Labels for the table
$rowLabel0 = "Group A";
$rowLabel1 = "Group B";
$colLabel0 = "Success";
$colLabel1 = "Failure";

# Identify which cell is which for the prompt
$cellNames = array(
  "Group A, Success",
  "Group A, Failure",
  "Group B, Success",
  "Group B, Failure"
);

# Create the specific prompts for the 3 parts
$prompt0 = "Expected count for " . $cellNames[$cellsToCompute[0]];
$prompt1 = "Expected count for " . $cellNames[$cellsToCompute[1]];
$prompt2 = "Expected count for " . $cellNames[$cellsToCompute[2]];

// === QUESTION TEXT ===
A researcher is testing for independence between two variables. The observed counts are shown in the table below:

<table border="1" style="border-collapse: collapse; text-align: center;">
  <tr>
    <th></th>
    <th>`$colLabel0`</th>
    <th>`$colLabel1`</th>
    <th>Total</th>
  </tr>
  <tr>
    <th>`$rowLabel0`</th>
    <td>`$obs00`</td>
    <td>`$obs01`</td>
    <td>`$row0`</td>
  </tr>
  <tr>
    <th>`$rowLabel1`</th>
    <td>`$obs10`</td>
    <td>`$obs11`</td>
    <td>`$row1`</td>
  </tr>
  <tr>
    <th>Total</th>
    <td>`$col0`</td>
    <td>`$col1`</td>
    <td>`$grandTotal`</td>
  </tr>
</table>

<br>
Assuming the two variables are independent, calculate the expected counts for the following cells. Round your answers to two decimal places.

<p>(a) `$prompt0`: $answerbox[0]</p>
<p>(b) `$prompt1`: $answerbox[1]</p>
<p>(c) `$prompt2`: $answerbox[2]</p>

// === ANSWER ===
$solutionguide = 'The expected count for a cell in a contingency table is calculated using the formula: 
Expected Count = (Row Total * Column Total) / Grand Total. 
For example, for the first cell: (' . $row0 . ' * ' . $col0 . ') / ' . $grandTotal . ' = ' . round($exp00, 2) . '.';

// === NAME - DESCRIPTION:  ===
// === SET QUESTION TYPE TO: choices ===

// === COMMON CONTROL ===
// We generate a set of points that are either clearly linear (with noise) or clearly non-linear.
$linear_case = rand(0, 1);

// Generate 10 points
$x_vals = array();
$y_vals = array();

if ($linear_case == 0) {
    // Linear trend: y = mx + b + noise
    $m = rand(1, 5);
    $b = rand(0, 10);
    for ($i = 0; $i < 10; $i++) {
        $x = $i + 1;
        $noise = rand(-2, 2);
        $x_vals[] = $x;
        $y_vals[] = ($m * $x) + $b + $noise;
    }
    $answer = 0; // Yes, it is roughly linear
    $trend_desc = "roughly linear";
} else {
    // Non-linear trend: y = x^2 or similar
    for ($i = 0; $i < 10; $i++) {
        $x = $i + 1;
        $noise = rand(-2, 2);
        $x_vals[] = $x;
        $y_vals[] = ($x * $x) + $noise;
    }
    $answer = 1; // No, it is not roughly linear
    $trend_desc = "clearly non-linear";
}

// Create the SVG scatterplot
$width = 300;
$height = 200;
$padding = 40;

// Find bounds for scaling
$min_x = min($x_vals);
$max_x = max($x_vals);
$min_y = min($y_vals);
$max_y = max($y_vals);

$scale_x = ($width - 2 * $padding) / ($max_x - $min_x);
$scale_y = ($height - 2 * $padding) / ($max_y - $min_y);

$points_svg = "";
foreach ($x_vals as $idx => $x) {
    $px = $padding + ($x - $min_x) * $scale_x;
    $py = $height - $padding - ($y_vals[$idx] - $min_y) * $scale_y;
    $points_svg .= "<circle cx='$px' cy='$py' r='3' fill='blue' />";
}

// Draw axes
$axes = "<line x1='$padding' y1='".($height - $padding)."' x2='".($width - $padding)."' y2='".($height - $padding)."' stroke='black' />"; // X axis
$axes .= "<line x1='$padding' y1='$padding' x2='$padding' y2='".($height - $padding)."' stroke='black' />"; // Y axis
$axes .= "<text x='".($width/2)."' y='".($height - 10)."' text-anchor='middle' font-size='12'>Variable X</text>";
$axes .= "<text x='15' y='".($height/2)."' text-anchor='middle' font-size='12' transform='rotate(-90 15,".($height/2).")'>Variable Y</text>";

$plot_svg = "<svg width='$width' height='$height' xmlns='http://www.w3.org/2000/svg'>$axes $points_svg</svg>";

$questions[0] = "Yes, the data show scatter around a roughly linear trend";
$questions[1] = "No, the data do not show a roughly linear trend";

// === QUESTION TEXT ===
<p>Examine the scatterplot below:</p>
<div style="margin: 20px 0;">
$plot_svg
</div>
<p>Does the data show scatter around a roughly linear trend?</p>
$answerbox

// === ANSWER ===
$solutionguide = 'To determine if a trend is roughly linear, look at the overall shape of the points. If they cluster around a straight line, the trend is linear. In this case, the generated data was ' . $trend_desc . '.';

// === NAME - DESCRIPTION: Bar Graph of Counts Versus Percentages - Recover group size and interpret relative frequency ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
$categories = array("Red", "Blue", "Green", "Yellow");
$nCats = count($categories);

// Generate counts that sum to a nice total for percentages
$total = randfrom(array(40, 50, 80, 100, 200));

// Distribute the total across categories
$counts = array();
$currentSum = 0;
for ($i = 0; $i < $nCats - 1; $i++) {
    // Ensure each category has at least 2 and doesn't take too much
    $val = rand(2, floor(($total - $currentSum - ($nCats - 1 - $i) * 2) / 2));
    $counts[$i] = $val;
    $currentSum += $val;
}
$counts[$nCats - 1] = $total - $currentSum;

// To shuffle categories and counts together without using jointshuffle on a single array,
// we shuffle the indices.
$indices = array();
for ($i = 0; $i < $nCats; $i++) {
    $indices[$i] = $i;
}
sortarray($indices); // This is a simple way to randomize the order of indices

$data = array();
for ($i = 0; $i < $nCats; $i++) {
    $idx = $indices[$i];
    $data[$i] = array("cat" => $categories[$idx], "count" => $counts[$idx]);
}

// Pick one category for the calculation part
$targetIdx = rand(0, $nCats - 1);
$targetCat = $data[$targetIdx]["cat"];
$targetCount = $data[$targetIdx]["count"];
$targetPct = ($targetCount / $total) * 100;

// Prepare the tables for display
$tableCounts = "";
$tablePct = "";
for ($i = 0; $i < $nCats; $i++) {
    $pct = ($data[$i]["count"] / $total) * 100;
    $tableCounts .= "<tr><td>" . $data[$i]["cat"] . "</td><td>" . $data[$i]["count"] . "</td></tr>";
    $tablePct .= "<tr><td>" . $data[$i]["cat"] . "</td><td>" . round($pct, 1) . "%</td></tr>";
}

$answer[0] = $total;
$answer[1] = round($targetPct, 1);
$answer[2] = 0; // Correct choice for the shape question
$questions[2] = array(
    "The percentages are calculated by dividing each count by the same total, so the relative proportions remain the same.",
    "The percentages are larger numbers than the counts, so the bars must grow taller.",
    "Percentages always create a symmetric distribution regardless of the original counts.",
    "The total count is lost when converting to percentages, which changes the scale of the x-axis."
);

$anstypes = "number,number,choices";
$strflags[0] = "trim_whitespace";
$strflags[1] = "trim_whitespace";
$strflags[2] = "ignore_case,trim_whitespace";

// === QUESTION TEXT ===
A researcher collected data on the favorite colors of a group of participants. The results are shown in the two tables below.

<p style="text-align:center;"><b>Table 1: Counts</b></p>
<table border="1" style="margin: 0 auto;">
