// IMathAS does not support 'do...while' loops. We must use a 'while' loop.
$det = 0;
while ($det == 0 || ($det != 1 && $det != -1)) {
    $a11 = rand(-3, 3); $a12 = rand(-3, 3); $a13 = rand(-3, 3);
    $a21 = rand(-3, 3); $a22 = rand(-3, 3); $a23 = rand(-3, 3);
    $a31 = rand(-3, 3); $a32 = rand(-3, 3); $a33 = rand(-3, 3);

    // Determinant of 3x3
    $det = $a11*($a22*$a33 - $a23*$a32) - $a12*($a21*$a33 - $a23*$a31) + $a13*($a21*$a32 - $a22*$a31);
}

// Compute the cofactors
$C11 = ($a22*$a33 - $a23*$a32);
$C12 = -($a21*$a33 - $a23*$a31);
$C13 = ($a21*$a32 - $a22*$a31);

$C21 = -($a12*$a33 - $a13*$a32);
$C22 = ($a11*$a33 - $a13*$a31);
$C23 = -($a11*$a32 - $a12*$a31);

$C31 = ($a12*$a23 - $a13*$a22);
$C32 = -($a11*$a23 - $a13*$a21);
$C33 = ($a11*$a22 - $a12*$a21);

// A_inv = (1/det) * adj(A). Note: adj(A) is the transpose of the cofactor matrix.
$inv11 = (1/$det) * $C11; $inv12 = (1/$det) * $C21; $inv13 = (1/$det) * $C31;
$inv21 = (1/$det) * $C12; $inv22 = (1/$det) * $C22; $inv23 = (1/$det) * $C32;
$inv31 = (1/$det) * $C13; $inv32 = (1/$det) * $C23; $inv33 = (1/$det) * $C33;

// Define B as a column vector of small integers
$b1 = rand(-5, 5);
$b2 = rand(-5, 5);
$b3 = rand(-5, 5);

// Solve AX = B  => X = A_inv * B
$x1 = $inv11*$b1 + $inv12*$b2 + $inv13*$b3;
$x2 = $inv21*$b1 + $inv22*$b2 + $inv23*$b3;
$x3 = $inv31*$b1 + $inv32*$b2 + $inv33*$b3;

$answer[0] = "[[$inv11,$inv12,$inv13],[$inv21,$inv22,$inv23],[$inv31,$inv32,$inv33]]";
