// === NAME - DESCRIPTION: Precalculus - Identify amplitude from sine equation ===
// === SET QUESTION TYPE TO: choices ===

// === COMMON CONTROL ===
// Amplitude must be positive.
$amp = rand(1, 12);
// Period is 2*pi/b. We'll pick a b that makes the period a clean multiple of pi or a fraction.
$b_vals = array(0.5, 1, 2, 4, 0.25);
$b = randfrom($b_vals);
// Vertical shift
$k = rand(-10, 10);

// Construct the equation string for display
// Using a simple form: y = a sin(bx) + k
$eq_text = "y = " . $amp . "sin(" . $b . "x) " . ($k >= 0 ? "+ " : "- ") . abs($k);

// Correct answer
$correct = $amp;

// Generate distractors
$distractors = array();
while (count($distractors) < 3) {
    // Distractors often confuse amplitude with vertical shift, period, or the coefficient b
    $d = rand(1, 20);
    if ($d != $correct && !in_array($d, $distractors)) {
        $distractors[] = $d;
    }
}

// Combine correct answer and distractors into one array
$options = array($correct, $distractors[0], $distractors[1], $distractors[2]);

// jointshuffle requires two arrays to shuffle them in tandem. 
// To shuffle a single array, we create a dummy array of the same size.
$dummy = array(0, 1, 2, 3);
jointshuffle($options, $dummy);

// Initialize $questions as an array
$questions = array();
$final_idx = -1;

for ($i = 0; $i < 4; $i++) {
    $val = $options[$i];
    $questions[$i] = (string)$val;
    if ($val == $correct) {
        $final_idx = $i;
    }
}

$answer = $final_idx;

